import { GmlConstructor, GmlProject, GmlType } from './gml-parser';

export interface GenerateOptions {
  /** Pick the messages list from the file whose path contains this text. */
  listFrom?: string;
  /** Module the generated file imports QNet from. Default "qnet-node". */
  importFrom?: string;
  /** Shown in the header comment. */
  sourceLabel?: string;
}

export interface GenerateResult {
  source: string;
  messageNames: string[];
  warnings: string[];
}

/**
 * Builds a TypeScript module with one @QSerializable class per GameMaker message constructor,
 * plus `messages`, the list in the same order the GameMaker game registers it.
 */
export function generateTypeScript(project: GmlProject, options: GenerateOptions = {}): GenerateResult {
  const warnings: string[] = [];
  const list = chooseList(project, options.listFrom, warnings);

  const constructors = list.map((name) => {
    const found = project.constructors.get(name);
    if (!found) {
      throw new Error(
        `"${name}" is in the messages list (${listFile(project, list)}) but no constructor named ${name} was found`,
      );
    }
    return found;
  });

  for (const ctor of constructors) {
    if (ctor.manual) continue;
    if (ctor.fields.length === 0 && ctor.params.length > 0) {
      warnings.push(`${ctor.name}: no "field = _param;" assignments found, so it has no fields`);
    }
    for (const field of ctor.fields) {
      checkType(field.param.type, ctor, field.name, list);
    }
  }

  const order = declarationOrder(constructors);
  const declared = new Set<string>();
  const usedBufferTypes = new Set<string>();
  let usesLazy = false;

  const classes = order.map((ctor) => {
    const text = emitClass(ctor, declared, usedBufferTypes, () => (usesLazy = true));
    declared.add(ctor.name);
    return text;
  });

  const imports = ['QSerializable', 'Field', ...(usesLazy ? ['lazy'] : []), ...[...usedBufferTypes].sort()];
  const header = [
    '// Generated by qnet-generate from a GameMaker project. Do not edit: re-run the generator instead.',
    options.sourceLabel ? `// Source: ${options.sourceLabel}` : undefined,
    `// Messages list from: ${listFile(project, list)}`,
    '//',
    '// Field names and the list order are the wire format and must match the GameMaker project.',
    '/* eslint-disable */',
  ]
    .filter((line) => line !== undefined)
    .join('\n');

  const source = [
    header,
    `import { ${imports.join(', ')} } from '${options.importFrom ?? 'qnet-node'}';`,
    '',
    classes.join('\n\n'),
    '',
    '/** Every message, in the order the GameMaker project registers them. Pass this to new QNetwork({ messages }). */',
    `export const messages = [${list.join(', ')}];`,
    '',
  ].join('\n');

  return { source, messageNames: list, warnings };
}

function chooseList(project: GmlProject, listFrom: string | undefined, warnings: string[]): string[] {
  const lists = project.messageLists;
  if (lists.length === 0) {
    throw new Error('No messages list found. Expected new QNetwork({ messages: [A, B] }) or new QSerializer([A, B]).');
  }
  if (listFrom) {
    const picked = lists.find((list) => list.file.includes(listFrom));
    if (!picked)
      throw new Error(`No messages list in a file matching "${listFrom}". Found: ${lists.map((l) => l.file)}`);
    return picked.names;
  }
  const distinct = new Map<string, { names: string[]; files: string[] }>();
  for (const list of lists) {
    const key = list.names.join(',');
    const entry = distinct.get(key) ?? { names: list.names, files: [] };
    entry.files.push(list.file);
    distinct.set(key, entry);
  }
  const ranked = [...distinct.values()].sort(
    (a, b) => b.names.length - a.names.length || b.files.length - a.files.length,
  );
  if (ranked.length > 1) {
    warnings.push(
      `Found ${ranked.length} different messages lists; ` +
        `using [${ranked[0].names.join(', ')}] from ${ranked[0].files.join(', ')}. ` +
        'Pass --list-from <file> to choose another.',
    );
  }
  return ranked[0].names;
}

function listFile(project: GmlProject, list: string[]) {
  return project.messageLists.find((l) => l.names.join(',') === list.join(','))?.file ?? '?';
}

function checkType(type: GmlType, ctor: GmlConstructor, field: string, list: string[]) {
  if (type.kind === 'array') return checkType(type.element, ctor, field, list);
  if (type.kind === 'literal') {
    throw new Error(
      `${ctor.name}.${field} defaults to "${type.text}", which is not a buffer type, array or struct. ` +
        'Use MANUAL_SERIALIZATION for messages that are not declared with buffer types.',
    );
  }
  if (type.kind === 'struct' && !list.includes(type.name)) {
    throw new Error(`${ctor.name}.${field} uses ${type.name}, which is not in the messages list`);
  }
}

/** Classes that others nest come first; self-references and cycles fall back to lazy(). */
function declarationOrder(constructors: GmlConstructor[]): GmlConstructor[] {
  const byName = new Map(constructors.map((c) => [c.name, c]));
  const ordered: GmlConstructor[] = [];
  const state = new Map<string, 'visiting' | 'done'>();
  const visit = (ctor: GmlConstructor) => {
    if (state.get(ctor.name)) return;
    state.set(ctor.name, 'visiting');
    for (const dependency of structDependencies(ctor)) {
      const next = byName.get(dependency);
      if (next && !state.get(dependency)) visit(next);
    }
    state.set(ctor.name, 'done');
    ordered.push(ctor);
  };
  constructors.forEach(visit);
  return ordered;
}

function structDependencies(ctor: GmlConstructor): string[] {
  const names: string[] = [];
  const walk = (type: GmlType) => {
    if (type.kind === 'array') walk(type.element);
    else if (type.kind === 'struct') names.push(type.name);
  };
  if (!ctor.manual) ctor.fields.forEach((field) => walk(field.param.type));
  return names;
}

function emitClass(ctor: GmlConstructor, declared: Set<string>, usedBufferTypes: Set<string>, usedLazy: () => void) {
  const lines: string[] = [];
  if (ctor.manual) {
    lines.push(
      '/** Uses MANUAL_SERIALIZATION in GameMaker. ' +
        `Supply its codec with implementManual(${ctor.name}, { write, read }). */`,
    );
    lines.push('@QSerializable({ manual: true })');
  } else {
    lines.push('@QSerializable');
  }
  lines.push(`export class ${ctor.name} {`);

  for (const field of ctor.fields) {
    const type = field.param.type;
    if (ctor.manual) {
      lines.push(`  ${field.name}: ${literalTsType(field.param.defaultText)};`);
    } else {
      lines.push(`  @Field(${fieldExpression(type, ctor.name, declared, usedBufferTypes, usedLazy)})`);
      lines.push(`  ${field.name}: ${tsType(type)};`);
    }
  }

  // Constructor mirrors the GameMaker one: same parameters, same order.
  const assigned = ctor.params.map((param) => ({ param, field: ctor.fields.find((f) => f.param === param) }));
  const args = assigned.map(({ param, field }) => {
    const argName = param.name.replace(/^_+/, '') || param.name;
    const type = ctor.manual ? literalTsType(param.defaultText) : tsType(param.type);
    const value = ctor.manual ? literalDefault(param.defaultText) : defaultValue(param.type);
    return { argName, type, value, field };
  });
  lines.push('');
  lines.push(`  constructor(${args.map((a) => `${a.argName}: ${a.type} = ${a.value}`).join(', ')}) {`);
  for (const a of args) if (a.field) lines.push(`    this.${a.field.name} = ${a.argName};`);
  lines.push('  }');
  lines.push('}');
  return lines.join('\n');
}

function fieldExpression(
  type: GmlType,
  owner: string,
  declared: Set<string>,
  usedBufferTypes: Set<string>,
  usedLazy: () => void,
): string {
  switch (type.kind) {
    case 'buffer':
      usedBufferTypes.add(type.name);
      return type.name;
    case 'array':
      return `[${fieldExpression(type.element, owner, declared, usedBufferTypes, usedLazy)}]`;
    case 'struct':
      if (declared.has(type.name)) return type.name;
      usedLazy();
      return `lazy(() => ${type.name})`;
    default:
      return 'undefined as never';
  }
}

function tsType(type: GmlType): string {
  switch (type.kind) {
    case 'buffer':
      return type.name === 'buffer_string'
        ? 'string'
        : type.name === 'buffer_bool'
          ? 'boolean'
          : type.name === 'buffer_u64'
            ? 'bigint'
            : 'number';
    case 'array':
      return `${tsType(type.element)}[]`;
    case 'struct':
      return type.name;
    default:
      return 'unknown';
  }
}

function defaultValue(type: GmlType): string {
  switch (type.kind) {
    case 'buffer':
      return type.name === 'buffer_string'
        ? "''"
        : type.name === 'buffer_bool'
          ? 'false'
          : type.name === 'buffer_u64'
            ? '0n'
            : '0';
    case 'array':
      return '[]';
    case 'struct':
      return `new ${type.name}()`;
    default:
      return 'undefined as never';
  }
}

function literalTsType(text: string): string {
  if (/^-?\d/.test(text)) return 'number';
  if (/^["']/.test(text)) return 'string';
  if (/^(true|false)$/.test(text)) return 'boolean';
  if (text.startsWith('[')) return 'unknown[]';
  return 'any';
}

function literalDefault(text: string): string {
  if (/^-?[\d.]+$/.test(text)) return text;
  if (/^["']/.test(text)) return "''"; // contents were blanked by the parser
  if (/^(true|false)$/.test(text)) return text;
  if (text.startsWith('[')) return '[]';
  return 'undefined';
}
